CREATE OR REPLACE VIEW v_wallet_ledger AS SELECT w.user_id,l.entry_id,l.transaction_id,j.transaction_kind,j.created_at,l.signed_amount,SUM(l.signed_amount) OVER(PARTITION BY w.user_id ORDER BY l.entry_id ROWS UNBOUNDED PRECEDING) running_balance FROM ledger_entries l JOIN wallets w ON w.account_id=l.account_id JOIN journal_transactions j ON j.transaction_id=l.transaction_id;
CREATE OR REPLACE VIEW v_issue_funding AS SELECT i.issue_id,i.repository_id,COALESCE(p.amount,0) total_pledged,e.held_amount escrow_held,COALESCE(r.amount,0) total_released,COALESCE(f.amount,0) total_refunded,COALESCE(p.amount,0)-e.held_amount-COALESCE(r.amount,0)-COALESCE(f.amount,0) conservation_delta,i.is_disputed FROM issues i JOIN escrows e USING(issue_id) LEFT JOIN(SELECT issue_id,SUM(amount) amount FROM pledges GROUP BY issue_id)p USING(issue_id) LEFT JOIN(SELECT m.issue_id,SUM(r.amount) amount FROM releases r JOIN milestones m USING(milestone_id) GROUP BY m.issue_id)r USING(issue_id) LEFT JOIN(SELECT p.issue_id,SUM(f.amount) amount FROM refunds f JOIN pledges p USING(pledge_id) GROUP BY p.issue_id)f USING(issue_id);
CREATE OR REPLACE VIEW v_reputation AS SELECT NULL repository_id,u.user_id,COALESCE(SUM(e.points),0) raw_points,GREATEST(0,COALESCE(SUM(e.points),0)) displayed_score FROM users u LEFT JOIN reputation_events e USING(user_id) GROUP BY u.user_id UNION ALL SELECT r.repository_id,u.user_id,COALESCE(SUM(e.points),0),GREATEST(0,COALESCE(SUM(e.points),0)) FROM users u CROSS JOIN repositories r LEFT JOIN reputation_events e ON e.user_id=u.user_id AND e.repository_id=r.repository_id GROUP BY r.repository_id,u.user_id;
CREATE OR REPLACE VIEW v_latest_pr_reviews AS SELECT pr_id,reviewer_id,review_id,share_revision,decision,comment_text,created_at FROM(SELECT v.*,ROW_NUMBER() OVER(PARTITION BY v.pr_id,v.reviewer_id ORDER BY v.created_at DESC,v.review_id DESC) row_no FROM pr_reviews v JOIN pull_requests p ON p.pr_id=v.pr_id AND p.share_revision=v.share_revision JOIN claims c ON c.claim_id=p.claim_id JOIN issues i ON i.issue_id=c.issue_id JOIN repository_maintainers m ON m.repository_id=i.repository_id AND m.user_id=v.reviewer_id WHERE NOT EXISTS(SELECT 1 FROM pr_contributors pc WHERE pc.pr_id=p.pr_id AND pc.user_id=v.reviewer_id))ranked WHERE row_no=1;
CREATE OR REPLACE VIEW v_reconciliation AS SELECT 'WALLET' entity_type,w.user_id entity_id,COALESCE((SELECT SUM(signed_amount) FROM ledger_entries WHERE account_id=w.account_id),0) expected_amount,w.balance actual_amount,w.balance-COALESCE((SELECT SUM(signed_amount) FROM ledger_entries WHERE account_id=w.account_id),0) delta FROM wallets w UNION ALL SELECT 'ESCROW',e.issue_id,COALESCE((SELECT SUM(signed_amount) FROM ledger_entries WHERE account_id=e.account_id),0),e.held_amount,e.held_amount-COALESCE((SELECT SUM(signed_amount) FROM ledger_entries WHERE account_id=e.account_id),0) FROM escrows e UNION ALL SELECT 'ISSUE',issue_id,total_pledged,escrow_held+total_released+total_refunded,-conservation_delta FROM v_issue_funding UNION ALL SELECT 'JOURNAL',j.transaction_id,0,COALESCE(SUM(l.signed_amount),0),COALESCE(SUM(l.signed_amount),0) FROM journal_transactions j LEFT JOIN ledger_entries l USING(transaction_id) GROUP BY j.transaction_id;
